import React from 'react';

const TABS = [
  { id: 'history',   label: 'Log',    icon: (active) => <svg viewBox="0 0 24 24" fill="none" stroke={active ? '#0a1a1a' : 'rgba(255,255,255,0.28)'} strokeWidth={active ? 2.2 : 1.8} strokeLinecap="round" strokeLinejoin="round" style={{width: active?20:17, height: active?20:17}}><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg> },
  { id: 'checkin',   label: 'Day',    icon: (active) => <svg viewBox="0 0 24 24" fill="none" stroke={active ? '#0a1a1a' : 'rgba(255,255,255,0.28)'} strokeWidth={active ? 2.2 : 1.8} strokeLinecap="round" strokeLinejoin="round" style={{width: active?20:17, height: active?20:17}}><circle cx="12" cy="12" r="9"/><path d="M8 12l3 3 5-5"/></svg> },
  { id: 'home',      label: 'Home',   icon: (active) => <svg viewBox="0 0 24 24" fill="none" stroke={active ? '#0a1a1a' : 'rgba(255,255,255,0.28)'} strokeWidth={active ? 2.2 : 1.8} strokeLinecap="round" strokeLinejoin="round" style={{width: active?20:17, height: active?20:17}}><path d="M3 12L12 4l9 8"/><path d="M5 10v9h4v-4h4v4h5v-9"/></svg> },
  { id: 'breathing', label: 'Breathe',icon: (active) => <svg viewBox="0 0 24 24" fill="none" stroke={active ? '#0a1a1a' : 'rgba(255,255,255,0.28)'} strokeWidth={active ? 2.2 : 1.8} strokeLinecap="round" strokeLinejoin="round" style={{width: active?20:17, height: active?20:17}}><path d="M12 4c0 0-4 3-4 7s4 5 4 9"/><path d="M12 4c0 0 4 3 4 7s-4 5-4 9"/></svg> },
];

const circleBase = {
  borderRadius: '50%',
  border: 'none',
  cursor: 'pointer',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  position: 'relative',
  overflow: 'hidden',
  transition: 'all 0.3s cubic-bezier(0.34,1.4,0.64,1)',
  WebkitTapHighlightColor: 'transparent',
};

export default function Nav({ page, setPage }) {
  return (
    <div style={{
      position: 'fixed', bottom: 28, left: '50%', transform: 'translateX(-50%)',
      zIndex: 300,
      display: 'flex', alignItems: 'flex-end', gap: 12,
    }}>
      {TABS.map(tab => {
        const active = page === tab.id;
        return (
          <div key={tab.id} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 7 }}>
            <button
              onClick={() => setPage(tab.id)}
              aria-label={tab.label}
              style={{
                ...circleBase,
                width: active ? 62 : 50,
                height: active ? 62 : 50,
                background: active
                  ? 'linear-gradient(175deg, rgba(210,248,248,1) 0%, rgba(126,200,200,0.92) 40%, rgba(38,140,140,0.96) 100%)'
                  : 'linear-gradient(175deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0.04) 100%)',
                boxShadow: active ? [
                  '0 1px 0 rgba(255,255,255,0.7) inset',
                  '0 -2px 0 rgba(0,0,0,0.12) inset',
                  '0 0 0 1px rgba(126,200,200,0.35)',
                  '0 8px 24px rgba(45,107,107,0.5)',
                  '0 2px 8px rgba(45,107,107,0.28)',
                ].join(',') : [
                  '0 1px 0 rgba(255,255,255,0.18) inset',
                  '0 -1px 0 rgba(0,0,0,0.15) inset',
                  '0 0 0 1px rgba(255,255,255,0.08)',
                  '0 4px 16px rgba(0,0,0,0.3)',
                ].join(','),
              }}
            >
              {/* top sheen */}
              <span style={{ position: 'absolute', top: 1, left: '10%', right: '10%', height: '44%', background: 'linear-gradient(180deg, rgba(255,255,255,' + (active ? '0.6' : '0.15') + ') 0%, transparent 100%)', borderRadius: '50%', pointerEvents: 'none' }} />
              {tab.icon(active)}
            </button>
            <span style={{
              fontSize: 9, fontWeight: 700, letterSpacing: '0.07em', textTransform: 'uppercase',
              color: active ? 'rgba(238,234,227,0.6)' : 'rgba(238,234,227,0.22)',
              transition: 'color 0.25s', whiteSpace: 'nowrap',
              fontFamily: "'Inter', sans-serif",
            }}>
              {tab.label}
            </span>
          </div>
        );
      })}
    </div>
  );
}
